mapper.select:
SELECT t.entId, t.entName, t.alarmCount, t.violationCount, t.deviceNormalRate, t.rectifyFinishRate, -- 自动排名：按违规次数降序，排名 1、2、3、4... RANK() OVER (ORDER BY t.violationCount DESC) AS `rank` FROM ( SELECT ei.id AS entId, ei.ent_name AS entName, COUNT(DISTINCT aim.id) AS alarmCount, COUNT(DISTINCT rr.id) AS violationCount, ROUND( (COUNT(DISTINCT CASE WHEN sd.status = '在线' THEN sd.device_code END) / COUNT(DISTINCT sd.device_code)) * 100, 2 ) AS deviceNormalRate, ROUND( (COUNT(DISTINCT CASE WHEN rr.review_status = '已完成' THEN rr.id END) / COUNT(DISTINCT rr.id)) * 100, 2 ) AS rectifyFinishRate FROM ai_alert_message aim INNER JOIN rectify_review rr ON aim.rectify_review_id = rr.id INNER JOIN enterprise_info ei ON rr.ent_id = ei.id INNER JOIN sys_device sd ON aim.device_code = sd.device_code WHERE aim.deleted = 0 AND rr.deleted = 0 AND ei.deleted = 0 AND sd.deleted = 0
AND aim.create_time >= #{beginTime}
AND aim.create_time < #{endTime}
GROUP BY ei.id, ei.ent_name ) t ORDER BY t.violationCount DESC

SELECT COUNT(DISTINCT ei.id) FROM ai_alert_message aim INNER JOIN rectify_review rr ON aim.rectify_review_id = rr.id INNER JOIN enterprise_info ei ON rr.ent_id = ei.id INNER JOIN sys_device sd ON aim.device_code = sd.device_code WHERE aim.deleted = 0 AND rr.deleted = 0 AND ei.deleted = 0 AND sd.deleted = 0
AND aim.create_time >= #{beginTime}
AND aim.create_time < #{endTime}
-- GROUP BY ei.id, ei.ent_name

SELECT aim.* FROM ai_alert_message aim INNER JOIN rectify_review rr ON aim.rectify_review_id = rr.id INNER JOIN enterprise_info ei ON rr.ent_id = ei.id INNER JOIN sys_device sd ON aim.device_code = sd.device_code WHERE aim.deleted = 0 AND rr.deleted = 0 AND ei.deleted = 0 AND sd.deleted = 0
AND aim.create_time >= #{beginTime}
AND aim.create_time < #{endTime}
AND rr.ent_id = #{entId}

SELECT rr.* FROM ai_alert_message aim INNER JOIN rectify_review rr ON aim.rectify_review_id = rr.id INNER JOIN enterprise_info ei ON rr.ent_id = ei.id INNER JOIN sys_device sd ON aim.device_code = sd.device_code WHERE aim.deleted = 0 AND rr.deleted = 0 AND ei.deleted = 0 AND sd.deleted = 0
AND aim.create_time >= #{beginTime}
AND aim.create_time < #{endTime}
AND rr.ent_id = #{entId}

SELECT distinct sd.* FROM ai_alert_message aim INNER JOIN rectify_review rr ON aim.rectify_review_id = rr.id INNER JOIN enterprise_info ei ON rr.ent_id = ei.id INNER JOIN sys_device sd ON aim.device_code = sd.device_code WHERE aim.deleted = 0 AND rr.deleted = 0 AND ei.deleted = 0 AND sd.deleted = 0
AND sd.status = '在线'
AND aim.create_time >= #{beginTime}
AND aim.create_time < #{endTime}
AND rr.ent_id = #{entId}

SELECT rr.* FROM ai_alert_message aim INNER JOIN rectify_review rr ON aim.rectify_review_id = rr.id INNER JOIN enterprise_info ei ON rr.ent_id = ei.id INNER JOIN sys_device sd ON aim.device_code = sd.device_code WHERE aim.deleted = 0 AND rr.deleted = 0 AND ei.deleted = 0 AND sd.deleted = 0 and rr.review_status = '已完成'
AND aim.create_time >= #{beginTime}
AND aim.create_time < #{endTime}
AND rr.ent_id = #{entId}
